insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('3c67f8bc-e84d-5ddf-806e-019f3af4e121', '75936d05-c088-522b-a756-2daa38e75e4d', '$13x = 42 - x$
What value of $x$ is the solution to the given equation?', '[]'::jsonb, 1, null),
  ('951bd881-49a4-50c7-a292-79445f5655b9', '75936d05-c088-522b-a756-2daa38e75e4d', 'An arborist measured and recorded the heights of red maple trees in a certain area. Of the red maple tree heights recorded in this area, the minimum was $42$ feet and the maximum was $57$ feet. Which inequality is true for all possible values of $t$, where $t$ represents the recorded height, in feet, of a red maple tree in this area?', '["$t \\le 42$", "$t \\ge 57$", "$t \\ge 99$", "$42 \\le t \\le 57$"]'::jsonb, 2, null),
  ('c5f4f85b-3212-5d9e-9f33-ca56c1d4495e', '75936d05-c088-522b-a756-2daa38e75e4d', 'Javier deposits \$45 in a savings account at the end of each week. At the beginning of the 1st week of a year there was \$700 in that savings account. How much money, in dollars, will be in the account at the end of the 6th week of the year?', '["$430$", "$745$", "$751$", "$970$"]'::jsonb, 3, null),
  ('122f8414-60f4-593f-a7c4-3d086d1f81e4', '75936d05-c088-522b-a756-2daa38e75e4d', 'The $y$-intercept of the graph of $y = x^{2} + 27$ is $(0,y)$. What is the value of $y$?', '[]'::jsonb, 4, null),
  ('f0e40960-d731-5afb-98e3-246ed0d996bb', '75936d05-c088-522b-a756-2daa38e75e4d', 'In $2000$, a census was taken to determine the population of a certain town. The graph gives the estimated population $y$, in thousands, of this town $x$ years after the $2000$ census was taken, where $0 \le x \le 5$. Based on the graph, which of the following is the closest to the estimated population $2$ years after the $2000$ census was taken?', '["$7400$", "$6200$", "$4300$", "$3000$"]'::jsonb, 5, '![figure](/q/may24/002.webp)'),
  ('60835178-0b48-503e-beb3-4b0c4d05229e', '75936d05-c088-522b-a756-2daa38e75e4d', '$f(x) = 5x + b$
For the linear function $f$, $b$ is a constant and $f(7) = 35$. What is the value of $b$?', '["$0$", "$1$", "$5$", "$7$"]'::jsonb, 6, null),
  ('e6a7a419-89f6-5d8e-816f-7605e895ffb0', '75936d05-c088-522b-a756-2daa38e75e4d', 'The function $h$ is defined by $h(x) = 5∣x∣$. What is the value of $h(-3)$?', '["$-15$", "$2$", "$8$", "$15$"]'::jsonb, 7, null),
  ('525412b2-ef8b-5b05-a73c-9a851097219e', '75936d05-c088-522b-a756-2daa38e75e4d', 'The table shows the frequency of values in a data set. What is the minimum value of the data set?', '["$1$", "$8$", "$13$", "$20$"]'::jsonb, 8, '| Value | Frequency |
| 13 | 8 |
| 20 | 1 |
| 27 | 8 |
| 34 | 6 |'),
  ('c054716f-3fa3-5060-8c79-2ab1f62e5482', '75936d05-c088-522b-a756-2daa38e75e4d', 'The list gives the mass, in grams, of 5 ruffed lemurs. $3910;3910;3130;3950;3150$ What is the mean mass, in grams, of these 5 ruffed lemurs?', '[]'::jsonb, 9, null),
  ('8c23974b-3ba5-5491-96c7-7a6f45557c3a', '75936d05-c088-522b-a756-2daa38e75e4d', '$y = 5(x - 3)$
$y = (x - 3)^{2}$
Which ordered pair $(x,y)$ is a solution to the given system of equations?', '["$(8,-5)$", "$(8,25)$", "$(3,8)$", "$(2,-5)$"]'::jsonb, 10, null),
  ('97ea99e9-85d1-56a2-9425-6973ea8f7ee5', '75936d05-c088-522b-a756-2daa38e75e4d', 'Scientists collected fallen acorns that each housed a colony of the ant species Pohioensis and analyzed each colony’s structure. For any of these colonies, if the colony has $x$ worker ants, the equation $y = 0.67x + 2.6$, where $20 \le x \le 110$, gives the predicted number of larvae, $y$, in the colony. If one of these colonies has $46$ worker ants, which of the following is closest to the predicted number of larvae in the colony?', '["$33$", "$49$", "$65$", "$150$"]'::jsonb, 11, null),
  ('cae48963-92b7-5f8a-95a1-02a801a39c42', '75936d05-c088-522b-a756-2daa38e75e4d', 'Liam has \$150 in an account. Each year he expects to have $2.8%$ more money in the account than he had the previous year. Which of the following models best describes how Liam expects the money in his account to change over time?', '["Decreasing exponential", "Decreasing linear", "Increasing exponential", "Increasing linear"]'::jsonb, 12, null),
  ('0b88a40e-cc49-50b2-8461-169775c017c7', '75936d05-c088-522b-a756-2daa38e75e4d', '$9x + 5y = 19$
$-9x - 3y = 7$
The solution to the given system of equations is $(x,y)$. What is the value of $2y$?', '[]'::jsonb, 13, null),
  ('c4ac6950-32dd-54d8-9496-10dea3342ae5', '75936d05-c088-522b-a756-2daa38e75e4d', 'Line $k$ is defined by $y = 6x + \frac{1}{9}$. Line $j$ is perpendicular to line $k$ in the $xy$-plane. What is the slope of line $j$?', '["$-9$", "$-\\frac{1}{6}$", "$\\frac{1}{9}$", "$6$"]'::jsonb, 14, null),
  ('e838fd82-173e-5de4-a1a5-8b5db915d966', '75936d05-c088-522b-a756-2daa38e75e4d', 'The product of a positive number $x$ and the number that is $7$ less than $x$ is equal to $228$. What is the value of $x$?', '[]'::jsonb, 15, null),
  ('49cb86cb-1bde-59a9-bd2e-572e68480c1c', '75936d05-c088-522b-a756-2daa38e75e4d', 'Raheem bought $9$ shirts that were each the same price. He used a coupon for \$54 off the entire purchase. The cost for the entire purchase after using the coupon was \$108. What was the original price, in dollars, for $1$ shirt?', '[]'::jsonb, 16, null),
  ('308d2607-ceb6-52c0-8faa-5df3bd94ede4', '75936d05-c088-522b-a756-2daa38e75e4d', '$7∣x - 7∣ = 42$
What is the sum of the solutions to the given equation?', '["$-6$", "$0$", "$14$", "$49$"]'::jsonb, 17, null),
  ('2751dcc3-d2ac-5428-b91a-5f84dac0b7c0', '75936d05-c088-522b-a756-2daa38e75e4d', 'In the figure, $RT = TU$, the measure of angle $V ST$ is $23°$, and the measure of angle $RV S$ is $34°$. What is the value of $x$?', '[]'::jsonb, 18, '![figure](/q/may24/003.webp)'),
  ('e50f13e6-b0a5-5b22-99fb-81a6d20f646b', '75936d05-c088-522b-a756-2daa38e75e4d', 'A cube has an edge length of $82$ inches. A solid sphere with a radius of $41$ inches is inside the cube, such that the sphere touches the center of each face of the cube. To the nearest cubic inch, what is the volume of the space in the cube <u>not</u> taken up by the sphere?', '["$262,672$", "$288,532$", "$334,846$", "$546,087$"]'::jsonb, 19, null),
  ('1b0eb920-e94a-5e2c-ad85-12534f99885e', '75936d05-c088-522b-a756-2daa38e75e4d', 'The function $h$ is defined by $h(x) = a^{x} + b$, where $a$ and $b$ are positive constants. The graph of $y =$ $h(x)$ in the $xy$-plane passes through the points $(0,8)$ and $(2,32)$. What is the value of $ab$?', '["$32$", "$35$", "$40$", "$64$"]'::jsonb, 20, null),
  ('f9a28bf2-71a5-57a9-ac30-52d1464465d3', '75936d05-c088-522b-a756-2daa38e75e4d', '$f(x) = k(1.84)^{x}$
The function $f$ is defined by the given equation, where $k$ is a constant. The value of $f(x)$ increases by $p%$ for every increase of $x$ by 1. For which of the following functions, where $k$ is a constant, does the value of $g(x)$ increase by $p%$ for every increase of $x$ by 4?', '["$g(x) = k(1.84\\frac{1}{4})$", "$g(x) = k(1.84)^{4}$", "$g(x) = k(1.84)^{x-4}$", "$g(x) = k(1.84)^{x+4}$"]'::jsonb, 21, null),
  ('c2c79349-55ef-5e7e-8a49-a601f15ad7cd', '75936d05-c088-522b-a756-2daa38e75e4d', 'The function $f$ is defined by the given equation, If $f(a) = -5a$, where $a$ is a constant, what is the value of $a$? The function is given by:
$f(x) =$$\sqrt{5x + 6}$', '["$\\frac{3}{5}$", "$\\frac{2}{5}$", "$-\\frac{2}{5}$", "$-\\frac{3}{5}$"]'::jsonb, 22, null)
